/* hired or not (JT 2026-10-01: start with no crew; hire them in the store). A new hand shows up with bare hands and a pan,
   like you: shallow holes, washed at the water drums. A shovel and a bucket (the sifter) are up to you. */
const crewHired=b=>crewHas(b,'hired');
const crewSifts=b=>crewHas(b,'bucket')||crewHas(b,'bucket2')||crewHas(b,'bucket3');
const crewDepth=b=>crewHas(b,'shovel')?FIVE_FT:SIM.HANDS.depth;   // how deep his holes go
const crewThirst=b=>crewHas(b,'canteen3')?0.35:crewHas(b,'canteen')?0.65:1;   // how long and how often he stops for water
/* his own health, stamina and water (JT 2026-10-01: the crew panel, 78-hud.js). Digging tires him and dries him out;
   rests bring his stamina back; low on water, he walks in to the water drums to fill up (a bigger canteen
   holds more, so fewer trips). Health only drops when an animal gets him (crewKO); the nurse puts it right. */
const crewWaterMax=b=>100*(crewHas(b,'canteen3')?2.3:crewHas(b,'canteen')?1.6:1);
const CREW_WATER_LOW=0.3;   // under this share of his canteen he goes for water at his next rest
function crewNeeds(b,dt){
  const s=b.state,cap=crewWaterMax(b);
  if(s==='inside'){b.stam=Math.min(100,b.stam+20*dt);b.water=Math.min(cap,b.water+25*dt);return}   // the tent's water cooler, and his bunk
  if(s==='dig'){b.stam=Math.max(0,b.stam-2.2*dt);b.water=Math.max(0,b.water-0.9*dt)}
  else if(s==='rest'||s==='siftq'||s==='down'){b.stam=Math.min(100,b.stam+12*dt);b.water=Math.max(0,b.water-0.15*dt)}
  else if(s==='ko'){b.stam=Math.min(100,b.stam+6*dt)}
  else{b.stam=Math.min(100,b.stam+2*dt);b.water=Math.max(0,b.water-0.3*dt)}
}
/* what he's up to, in a few words, for the crew panel */
function crewActivity(b){
  const s=b.state;
  if(s==='dig')return b.water<=0?'Digging, parched':b.stam<15?'Digging, worn out':'Digging';
  if(s==='rest')return b.stam<45?'Catching his breath':'Taking a breather';
  if(s==='walk'||s==='return')return'Walking to a new spot';
  if(s==='gateout'||s==='gatein')return b.errand==='sift'?'Taking his bucket in':b.errand==='pan'?'Taking his pan in to wash':b.errand==='water'?'Going in for water':curfewSoon()?'Heading in for the night':'Going to D Tent';
  if(s==='gotent')return curfewSoon()?'Heading in for the night':'Going to D Tent';
  if(s==='siftq')return SIFTQ.indexOf(b)===0?'Next at the sifter':`In line at the sifter (${SIFTQ.indexOf(b)} ahead)`;
  if(s==='sifting')return'Sifting his bucket';
  if(s==='drink')return b.wash?'Washing his pan':'Filling his canteen';
  if(s==='away')return'Not hired';
  if(s==='gatebackin'||s==='gatebackout')return'Heading back out';
  if(s==='indoor'||s==='inside')return curfewSoon()||clockT()>=DAYMS?(b.d.n==='Jim Bob'&&!b.xraySleeps?'Dealing cards in D Tent':'Asleep'):'On a break in D Tent';
  if(s==='tossed')return b.tossWhy==='mn'?'Blown sky-high by a landmine!':b.tossWhy==='tw'?'Caught in a twister!':b.tossWhy==='tb'?'Bowled over by a tumbleweed!':'Hit by a boulder!';
  if(s==='down')return'Getting back up';
  if(s==='ko')return`Knocked out (${{liz:'lizard',jav:'javelina',lion:'mountain lion',bite:'bitten'}[b.koWhy]||'hurt'})`;
  if(s==='held'||s==='flung')return'Being carried about';
  return s;
}
const CREW_GATE={x:0,out:25,in:30};   // the main gate: just outside, just inside
const GATE_LANE=4;                    // keep this clear either side of the path out of the gate (x 0)
function crewDigOK(x,z,b){
  if(inCamp(x,z)||Math.max(Math.abs(x),Math.abs(z))>EDGE-6)return false;
  if(Math.hypot(Math.max(-40-x,0,x-30),Math.max(27-z,0,z-56))<CAMP_NODIG+1.5)return false;   // well past the white line (10-core.js)
  if(Math.abs(x)<GATE_LANE&&z>0&&z<27)return false;   // not in the way out of the gate
  if(holeNear(x,z,2.9))return false;                    // fresh ground: no hole (anyone's) here yet
  for(const o of bots)if(o!==b&&(o.state==='walk'?Math.hypot(o.tx-x,o.tz-z)<3:o.hole&&Math.hypot(o.hole.x-x,o.hole.z-z)<3))return false;   // or about to be
  return true;
}
/* somewhere new to dig: close to (cx, cz) if there's room, further out if not */
function crewDigSpot(b,cx,cz){
  for(const R of[3.3,5,8,12,18,26,36])for(let k=0;k<16;k++){
    const a=botRng()*Math.PI*2,x=r1(cx+Math.cos(a)*R),z=r1(cz+Math.sin(a)*R);if(crewDigOK(x,z,b))return{x,z};
  }
  return null;
}
const bots=[];
for(const d of BOTDEF){
  const p=makePerson({skin:d.skin,band:d.band,hat:d.hat,body:d.body,hair:d.hair});scene.add(p.g);
  const sp=crewDigOK(r1(d.x),r1(d.z),null)?{x:r1(d.x),z:r1(d.z)}:crewDigSpot(null,d.x,Math.min(d.z,20))||{x:r1(d.x),z:12};
  const hole=addHole({x:sp.x,z:sp.z,d:0.2+botRng()*1.0,bot:true});touchHole(hole);
  p.g.position.set(hole.x,groundAt(hole.x,hole.z),hole.z);p.g.rotation.y=Math.PI+(botRng()-0.5);
  const L=makeLabel(p.g,d.n,'bot');
  bots.push({d,p,hole,L,state:'dig',t:0,dph:botRng(),talkT:4+botRng()*20,tx:0,tz:0,bucket:0,hp:100,stam:60+botRng()*40,water:50+botRng()*50});   // bucket: holes of sand so far
}
/* the D Tent door, from outside: where the crew walks to before ducking in for a break or the night */
const D_TENT_DOOR={x:D_TENT.x,z:D_TENT.z-D_TENT.hd-1.3};
/* Inside D Tent (the room sits underground at the tent's x/z): come in at the entry, hang your shovel on your own
   rack slot by the door, then go to your bunk. Jim Bob deals at the card table until 01:00 and takes the sixth bunk. */
const D_TI=TENTS.indexOf(D_TENT),D_ROOM_Z0=D_TENT.z-D_TENT.roomD;   // the room's door wall
const D_TENT_BUNKS=BUNKS.map((b,i)=>({b,i})).filter(o=>o.b.tent===D_TI).map(o=>o.i);
const BOT_BUNK={};BOTDEF.forEach((d,i)=>{BOT_BUNK[d.n]=D_TENT_BUNKS[d.n==='Jim Bob'?5:i-1]});   // Jim Bob is BOTDEF[0]; the rest take bunks 0-4
const D_ENTRY={x:D_TENT.x,z:D_ROOM_Z0+2.6},D_EXIT={x:D_TENT.x,z:D_ROOM_Z0+0.85};
/* the rack: six slots on the door wall, left of the doorway (the room model has the board, art/blender/interiors.py).
   Each crew member owns a slot; its shovel shows there while that shovel is racked. */
const RACK=BOTDEF.map((d,k)=>{
  const x=D_TENT.x-4.0+k*0.45,g=new T.Group(),F=TENT_FLOOR_Y;
  const hMat=new T.MeshStandardMaterial({color:0x8a6a44,roughness:0.85}),bMat=new T.MeshStandardMaterial({color:0x707472,roughness:0.6,metalness:0.2});
  const a=new T.Vector3(x,F+1.6,D_ROOM_Z0+0.28),b=new T.Vector3(x+0.05,F+0.35,D_ROOM_Z0+0.48),len=a.distanceTo(b);
  const handle=new T.Mesh(new T.CylinderGeometry(0.025,0.025,len,6),hMat);handle.position.copy(a).add(b).multiplyScalar(0.5);handle.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),b.clone().sub(a).normalize());
  const blade=new T.Mesh(new T.BoxGeometry(0.26,0.34,0.04),bMat);blade.position.set(x+0.06,F+0.2,D_ROOM_Z0+0.5);blade.rotation.x=-0.35;
  g.add(handle,blade);g.visible=false;ROOM_MESHES[D_TI].add(g);
  return{x,front:{x,z:D_ROOM_Z0+1.3},mesh:g};
});
function botBedPath(b){   // walk to beside your bunk (they run along the west wall), or round the table to the dealer's seat
  if(b.d.n==='Jim Bob'&&!b.xraySleeps){const s=D_TENT.dealerSeat;return[{x:s.x+2.5,z:s.z-4.75},{x:s.x+2.5,z:s.z},{x:s.x,z:s.z}]}   // round the east side of the card table
  const k=BUNKS[BOT_BUNK[b.d.n]];return[{x:k.x+1.4,z:k.z}];
}
function botIndoorSpot(b){return b.d.n==='Jim Bob'&&!b.xraySleeps?D_TENT.dealerSeat:BUNKS[BOT_BUNK[b.d.n]]}
function rackShovel(b,on){b.p.stowed=on;RACK[bots.indexOf(b)].mesh.visible=on}
const OUTDOOR=new Set(['dig','rest','walk','return','gateout','gatein','gotent','gatebackin','gatebackout','siftq','sifting','drink']);
/* ---- the sifter queue: the first in line sifts (beside the hopper), the rest wait in a line behind ---- */
const SIFTQ=[];
const SIFT_SLOTS=[[9.8,37.7],[11.2,36.9],[12.5,36.4],[13.8,35.9],[15.1,35.4],[16.4,35.0],[17.7,34.6]];
const siftSlot=i=>SIFT_SLOTS[Math.min(i,SIFT_SLOTS.length-1)];
function leaveSiftQ(b){const i=SIFTQ.indexOf(b);if(i>=0)SIFTQ.splice(i,1)}
function humanAtSifter(){   // a camper using the sifter right now: the crew waits for them
  const G=SIM.GOLD.SIFTER,near=(x,z)=>Math.hypot(x-G.x,z-G.z)<SIM.GOLD.SIFT_R;
  if(S.started&&S.tent==null&&!S.inTown&&near(P.x,P.z))return true;
  for(const R of remotes.values())if(R.room==null&&!R.tn&&near(R.tx,R.tz))return true;
  return false;
}
/* the gold from a crew member's bucket goes in the crew bank, once: only the lowest-id camper's screen pays it */
function crewPaysHere(){if(!online())return true;for(const id of remotes.keys())if(id<net.id)return false;return true}
function crewDeposit(b,gold){
  if(!crewPaysHere())return;
  logEv('crewSift',{n:b.d.n,gold});
  if(online())wsSend({t:'deposit',v:gold,bot:b.d.n});
  else{RUN.bank+=gold;saveRun();toast(`${b.d.n} sifted ${gold} gold into the crew bank.`,'',3200)}
}
/* the crew's buckets: carried by the bail while walking (86-walkie.js holdProp, like the first-aid kit), set down by
   the hole while digging (art/blender/sifter.py CampBucket) */
const CREW_CARRY=new Set(['walk','return','gateout','gatein','gotent','gatebackin','gatebackout','siftq','drink']);
let CREW_BUCKET_PARTS=null;modelParts('CampBucket').then(p=>{CREW_BUCKET_PARTS=p}).catch(()=>{});
function crewBucket(b,show){
  if(!b.gb){if(!CREW_BUCKET_PARTS||!show)return;b.gb=new T.Group();for(const pt of CREW_BUCKET_PARTS){const m=new T.Mesh(pt.geometry,pt.material);m.castShadow=true;b.gb.add(m)}scene.add(b.gb)}
  b.gb.visible=show;if(!show)return;
  const h=b.hole,ux=h.x-h.mx,uz=h.z-h.mz,ul=Math.hypot(ux,uz)||1,x=h.x+ux/ul*HOLE_R*1.2,z=h.z+uz/ul*HOLE_R*1.2;   // on the far side from the dirt pile
  b.gb.position.set(x,baseH(x,z),z);
}
function crewHands(b){
  const has=crewBucketMax(b)>0,carry=has&&CREW_CARRY.has(b.state)&&b.p.g.visible,held=b.p.held&&b.p.held.k==='bucket'&&b.p.held.t>0;   // no bucket bought for him: nothing to carry
  if(carry&&!held)holdProp(b.p,'bucket');else if(!carry&&held)releaseProp(b.p,'bucket');
  crewBucket(b,has&&(b.state==='dig'||b.state==='rest')&&b.p.g.visible);
}
const curfewSoon=()=>clockT()>=DAYMS-60000;   // the siren (82-patrol.js) through the night
const xrayBedtime=()=>clockT()>=tAtHour(1);    // 01:00 until dawn
function walkTo(b,x,z,dt,speed,y){   // true once there
  const g=b.p.g,dx=x-g.position.x,dz=z-g.position.z,d=Math.hypot(dx,dz);
  if(d<0.1)return true;
  const s=Math.min(d,dt*speed);g.position.x+=dx/d*s;g.position.z+=dz/d*s;g.rotation.y=Math.atan2(dx,dz);
  g.position.y=y!==undefined?y:groundAt(g.position.x,g.position.z);animPerson(b.p,speed>3?4:1,dt,0,speed>3?1:undefined);return false;
}
function goIndoor(b,path,then){b.state='indoor';b.path=path;b.then=then}
/* ---- grabbed (84-grab.js, hold R on one of them): you can pick a crew member up and carry them about, or throw them.
   They aren't networked, so only you see it. Let go and they land, grumble, and get back to work. ---- */
const crewGrabbable=b=>OUTDOOR.has(b.state)||b.state==='held'||b.state==='flung';
function crewGrabbed(b,on,throwDir){
  if(on){if(b.state!=='held'){b.heldFrom=b.state;b.state='held';b.v={x:0,y:0,z:0};leaveSiftQ(b);say(b.L,pick(['Hey! Put me down!','What are you doing?!','Not cool, man.','I\'m not a sack of potatoes!']),2500)}return}
  if(b.state!=='held')return;b.state='flung';b.handAt=null;
  if(throwDir){const th=SIM.GRAB.THROW*tune('grab.throw')*0.8;b.v={x:throwDir[0]*th,y:throwDir[1]*th+3,z:throwDir[2]*th};say(b.L,'WHOAAA!',1800)}
}
function crewHeldStep(b,dt){
  const g=b.p.g.position;
  if(b.state==='held'&&b.handAt){const h=b.handAt,ty=h[1]-0.75,k=Math.min(1,dt*9);   // dangling from your hands
    b.v.x=(h[0]-g.x)/Math.max(dt,1e-3)*k;b.v.y=(ty-g.y)/Math.max(dt,1e-3)*k;b.v.z=(h[2]-g.z)/Math.max(dt,1e-3)*k;
    g.x+=(h[0]-g.x)*k;g.z+=(h[2]-g.z)*k;g.y+=(Math.max(ty,groundAt(g.x,g.z))-g.y)*k;animPerson(b.p,7,dt);return}   // the Jump clip: legs kicking
  // flung or dropped: fall, land, then back to work
  b.v.y-=16*dt;g.x+=b.v.x*dt;g.y+=b.v.y*dt;g.z+=b.v.z*dt;b.v.x*=1-0.4*dt;b.v.z*=1-0.4*dt;
  const gy=groundAt(g.x,g.z);animPerson(b.p,7,dt);
  if(g.y<=gy){g.y=gy;if(Math.abs(b.v.y)>7)sfx.thud();b.v={x:0,y:0,z:0};
    say(b.L,pick(['Ow.','Thanks a lot.','I\'m telling the Warden.','My back...']),2200);
    b.state='return';b.tx=b.hole.x;b.tz=b.hole.z}
}
/* ---- the crew out in the weather (JT 2026-10-01): twisters, tumbleweeds and boulders throw them about (a ragdoll,
   26-ragdoll.js) but never hurt them: they lie there a moment, get up and carry on, bucket and all. The animals are
   another matter: a lizard, javelina, the lion or a snake/scorpion/hatchling that gets to one knocks him out. His
   bucket spills, and he wakes up in the nurse's office (back at camp) and has to walk out again. A slowdown, nothing
   worse. Like the rest of the crew, all of this happens on your screen only. ---- */
const CREW_NURSE={x:-1.5,z:33};   // where they come round, just inside the gate
const CREW_HOLD=new Set(['held','flung','tossed','down','ko']);
function crewToss(b,vx,vy,vz,why){
  if(!OUTDOOR.has(b.state))return;
  leaveSiftQ(b);b.preToss=b.state;b.tossWhy=why;b.state='tossed';b.v={x:vx,y:vy,z:vz};b.t=0;b.handAt=null;
  if(nearCam(b.p.g.position.x,b.p.g.position.z,40))say(b.L,pick({tw:['AAAAH!','Not again!','Put me DOWN!'],tb:['Get it off me!','WHOA!','Stupid weed!'],ls:['ROCK!','Ow, my everything!','Look out!'],mn:['AAAAAAAAAH!','WHO BURIES A MINE IN A LAKE?!','My eyebrows!','I can see the Warden\'s house from here!']}[why]||['WHOA!']),2200);
  logEv('crewToss',{n:b.d.n,why});
}
function crewKO(b,why){
  if(!OUTDOOR.has(b.state)&&b.state!=='tossed'&&b.state!=='down')return;
  leaveSiftQ(b);b.state='ko';b.koWhy=why;b.hp=0;b.t=2.6;b.v={x:0,y:0,z:0};b.handAt=null;
  const had=b.bucket||0;b.bucket=0;b.errand=null;   // the bucket spills: that sand's gone
  if(nearCam(b.p.g.position.x,b.p.g.position.z,45)){sfx.thud();say(b.L,{liz:'It BIT me!',jav:'Pig! PIG!',lion:'*whimper*',bite:'Something bit me!'}[why]||'Ow!',2600)}
  logEv('crewKO',{n:b.d.n,why,sand:had});
}
/* what's about to hit him: called every frame for a crew member out on the lake */
function crewHazards(b){
  const g=b.p.g.position;
  for(const tw of TW_LIVE.values()){if(tw.x==null)continue;const dx=g.x-tw.x,dz=g.z-tw.z,d=Math.hypot(dx,dz),r=TW_SUCK_R*(tw.s||1)+1;
    if(d<r){const a=Math.atan2(dz,dx)+1.2;crewToss(b,Math.cos(a)*9,11+Math.random()*4,Math.sin(a)*9,'tw');return}}
  for(const w of tbWeeds){if(w.dead||w.x==null)continue;const d=Math.hypot(g.x-w.x,g.z-w.z);
    if(d<w.r+0.8&&g.y+1.6>w.y-w.r&&g.y<w.y+w.r){crewToss(b,(w.vx||0)*0.9,7,(w.vz||0)*0.9,'tb');return}}
  for(const o of lsBoulders){if(o.settledT>=LS_SETTLE_TIME)continue;const sp=Math.hypot(o.vx,o.vz);if(sp<LS_HURT_SPEED)continue;
    const d=Math.hypot(g.x-o.x,g.z-o.z);if(d<o.r+0.55&&Math.abs(g.y+0.9-o.y)<o.r+1.2){crewToss(b,o.vx*0.8+(g.x-o.x)/(d||1)*3,6,o.vz*0.8+(g.z-o.z)/(d||1)*3,'ls');return}}
  if(inCamp(g.x,g.z))return;   // the animals don't come inside the fence
  for(const j of JAVV)if(j[3]===0&&Math.hypot(g.x-j[0],g.z-j[1])<1.0){crewKO(b,'jav');return}
  if(LIONV.active&&LIONV.hp>0&&Math.hypot(g.x-LIONV.x,g.z-LIONV.z)<1.6){crewKO(b,'lion');return}
  for(const v of ROV.values())if(['hatch','snake','scorp'].includes(v.k)&&v.g&&Math.hypot(g.x-v.g.position.x,g.z-v.g.position.z)<0.9){crewKO(b,'bite');return}
}
/* thrown, lying there, knocked out: the body's a ragdoll (26-ragdoll.js crewRag) and this moves it */
function crewHurtStep(b,dt){
  const g=b.p.g.position;
  if(b.state==='tossed'){b.v.y-=16*dt;g.x+=b.v.x*dt;g.y+=b.v.y*dt;g.z+=b.v.z*dt;b.v.x*=1-0.3*dt;b.v.z*=1-0.3*dt;
    g.x=clamp(g.x,-EDGE+2,EDGE-2);g.z=clamp(g.z,-EDGE+2,EDGE-2);const gy=groundAt(g.x,g.z);
    if(g.y<=gy&&b.v.y<0){g.y=gy;if(nearCam(g.x,g.z,30))sfx.thud();b.state='down';b.t=1.6+Math.random()}return}
  if(b.state==='down'){g.y=groundAt(g.x,g.z);if((b.t-=dt)<=0){b.state='return';b.tx=b.hole.x;b.tz=b.hole.z;say(b.L,pick(['I\'m okay.','Ugh.','Where\'s my bucket? Oh. Here.']),2000)}return}
  if(b.state==='ko'){g.y=groundAt(g.x,g.z);if((b.t-=dt)<=0){   // off to the nurse, and back out
    g.set(CREW_NURSE.x,groundAt(CREW_NURSE.x,CREW_NURSE.z),CREW_NURSE.z);if(b.p.rag){b.p.rag=null;b.p.ragBlend=0}b.hp=100;b.water=crewWaterMax(b);
    b.state='gatebackout';b.tx=CREW_GATE.x;b.tz=CREW_GATE.out;say(b.L,pick(['Back from the nurse. Lost my whole bucket.','The nurse says I\'m fine. My bucket isn\'t.','Okay. Starting that bucket over.']),3000)}}
}
/* the ragdoll pose for a crew member this frame (26-ragdoll.js), or null for his animation */
function crewRag(b){
  if(b.state==='tossed'||b.state==='flung')return{pin:0.15,flail:1.2};
  if(b.state==='down'||b.state==='ko')return{pin:0.03,flail:0};
  return null;
}
function updateBots(dt,now){
  if(PARTY.on)return;
  if(ZONE_H)return;   // the crew stays behind at camp while you're in another map (88-zones.js)
  const siren=curfewSoon();
  for(const b of bots){
    if(b.sinkOverride)continue;   // off pulling someone out of a sinkhole right now (87-sinkhole.js drives him instead)
    const g=b.p.g,indoors=b.state==='inside'||b.state==='indoor';
    /* sent back outside by something else (the party ending, a sinkhole rescue) while still in the room: step out at the door with your shovel */
    if(OUTDOOR.has(b.state)&&g.position.y<TENT_FLOOR_Y+1){g.position.set(D_TENT_DOOR.x,groundAt(D_TENT_DOOR.x,D_TENT_DOOR.z),D_TENT_DOOR.z);rackShovel(b,false)}
    g.visible=!indoors||S.tent===D_TI;
    if(DLG.open&&DLG.bot===b){ /* mid-conversation: stop and face the player */
      let dr=Math.atan2(P.x-g.position.x,P.z-g.position.z)-g.rotation.y;dr=Math.atan2(Math.sin(dr),Math.cos(dr));g.rotation.y+=dr*Math.min(1,dt*8);
      animPerson(b.p,0,dt);continue;
    }
    const asleep=b.state==='inside'&&(b.d.n!=='Jim Bob'||b.xraySleeps);
    b.talkT-=dt;if(b.talkT<=0){b.talkT=18+botRng()*28;if(!asleep)say(b.L,b.d.lines[Math.floor(botRng()*b.d.lines.length)])}
    /* the siren: drop everything and head for camp (running once it's gone), or turn back for the tent */
    if(!crewHired(b)){if(b.state!=='away'){leaveSiftQ(b);b.state='away';g.position.set(g.position.x,-200,g.position.z);if(b.gb)b.gb.visible=false}g.visible=false;b.L.el.style.display='none';continue}   // not on the crew (yet)
    if(b.state==='away'){   // just hired: he walks in through the gate with bare hands and a pan
      g.position.set(CREW_NURSE.x,groundAt(CREW_NURSE.x,CREW_NURSE.z),CREW_NURSE.z);g.visible=true;b.L.el.style.display='';b.bucket=0;b.hp=100;b.stam=100;b.water=crewWaterMax(b);b.errand=null;
      b.hole.d=crewDepth(b);b.state='gatebackout';b.tx=CREW_GATE.x;b.tz=CREW_GATE.out;say(b.L,pick(['Reporting for work.','Where do I dig?','I\'m on the crew? Okay.']),3000)}
    crewNeeds(b,dt);spadeLook(b.p,crewHas(b,'spade'));b.p.noShovel=!crewHas(b,'shovel');
    if(b.state==='held'||b.state==='flung'){g.visible=true;crewHeldStep(b,dt);continue}
    if(b.state==='tossed'||b.state==='down'||b.state==='ko'){g.visible=true;animPerson(b.p,b.state==='tossed'?7:3,dt);crewHurtStep(b,dt);continue}
    if(OUTDOOR.has(b.state)&&!siren)crewHazards(b);
    if(SIFTQ.includes(b)&&b.state!=='siftq'&&b.state!=='sifting')leaveSiftQ(b);   // sent off by something else (the party, a sinkhole rescue)
    if(OUTDOOR.has(b.state))crewHands(b);
    if(siren){
      if(b.state==='siftq'||b.state==='sifting'||b.state==='drink'){leaveSiftQ(b);b.errand=null;b.state='gotent';b.tx=D_TENT_DOOR.x;b.tz=D_TENT_DOOR.z}   // already inside the fence: straight to the tent, bucket and all
      if(b.state==='dig'||b.state==='rest'||b.state==='walk'||b.state==='return'||b.state==='gatebackout'){b.state='gateout';b.tx=0;b.tz=25;b.errand=null}
      else if(b.state==='gatebackin'){b.state='gotent';b.tx=D_TENT_DOOR.x;b.tz=D_TENT_DOOR.z}
    }
    if(b.state==='indoor'){
      /* walking a path inside the room, then doing b.then */
      const w=b.path[0];
      if(w){if(walkTo(b,w.x,w.z,dt,1.6,TENT_FLOOR_Y))b.path.shift();continue}
      b.t=(b.t||0)-dt;if(b.t>0){animPerson(b.p,0,dt);continue}
      if(b.then==='rack'){b.then='hang';b.t=0.6}   // a moment at the rack
      else if(b.then==='hang'){rackShovel(b,true);goIndoor(b,botBedPath(b),'settle')}
      else if(b.then==='settle'){
        const spot=botIndoorSpot(b);g.position.set(spot.x,TENT_FLOOR_Y,spot.z);b.state='inside';
        b.t=siren?null:20+botRng()*40;   // a daytime break lasts 20-60 s; a night lasts until a wake-up time after dawn
      }
      else if(b.then==='unrack'){rackShovel(b,false);goIndoor(b,[D_EXIT],'out')}
      else if(b.then==='out'){g.position.set(D_TENT_DOOR.x,groundAt(D_TENT_DOOR.x,D_TENT_DOOR.z),D_TENT_DOOR.z);g.rotation.y=Math.PI;b.state='gatebackin';b.tx=0;b.tz=30}
      continue;
    }
    if(b.state==='inside'){
      /* dealing at the card table (Jim Bob, until 01:00) or lying on your bunk */
      if(b.d.n==='Jim Bob'&&!b.xraySleeps){
        const st=SEATS.find(q=>q.tent===D_TI&&q.z>D_TENT.table.z+3);   // Jim Bob deals sitting on the far stool (86-sit.js)
        if(st)sitPose(b.p,st.x,TENT_FLOOR_Y+st.y,st.z,st.h,dt);else{g.position.y=TENT_FLOOR_Y;animPerson(b.p,0,dt)}
        if(xrayBedtime()){b.xraySleeps=true;goIndoor(b,[{x:D_TENT.dealerSeat.x+2.5,z:D_TENT.dealerSeat.z},{x:D_TENT.dealerSeat.x+2.5,z:D_TENT.dealerSeat.z-4.75},...botBedPath(b)],'settle')}
        else if(!siren&&b.t==null)b.t=0;   // a daytime visit's dealing ends when the day timer does
      }else{animPerson(b.p,0,dt);sleepPose(b.p,botIndoorSpot(b))}
      if(!siren){
        if(b.t==null)b.t=botRng()*40;   // morning: each gets up at their own time, 06:00-07:00
        b.t-=dt;
        if(b.t<=0){   // up: stand beside the bunk (or leave the dealer's seat), fetch your shovel and head out
          const seated=b.d.n==='Jim Bob'&&!b.xraySleeps,k=BUNKS[BOT_BUNK[b.d.n]];b.xraySleeps=false;
          if(!seated)g.position.set(k.x+1.4,TENT_FLOOR_Y,k.z);
          const s=D_TENT.dealerSeat;goIndoor(b,[...(seated?[{x:s.x+2.5,z:s.z},{x:s.x+2.5,z:s.z-4.75}]:[]),RACK[bots.indexOf(b)].front],'unrack');
        }
      }
      continue;
    }
    if(b.state==='dig'){
      const iv=b.d.rate>0.1?0.7:0.95,prev=b.dph;b.dph+=dt/iv;
      /* dirt leaves the shovel at the top of the toss and lands on this hole's pile */
      if(prev<0.72&&b.dph>=0.72&&nearCam(b.hole.x,b.hole.z,35)){const ux=b.hole.mx-g.position.x,uz=b.hole.mz-g.position.z,ul=Math.hypot(ux,uz)||1;puff(g.position.x+ux/ul*0.5,g.position.y+1.3,g.position.z+uz/ul*0.5,b.hole.mx,b.hole.mz,5)}
      if(b.dph>=1){b.dph-=1;b.hole.d=Math.min(crewDepth(b),b.hole.d+b.d.rate*1.25*(crewHas(b,'shovel')?1:0.35)*(crewHas(b,'spade')?1.6:1)*(b.water<=0||b.stam<15?0.5:1));/* parched or worn out: half speed */touchHole(b.hole)}
      /* stand in the hole with the dirt pile on the throwing side, and sink as it gets deeper */
      const ux=b.hole.mx-b.hole.x,uz=b.hole.mz-b.hole.z,ty=Math.atan2(-uz,ux);
      let dr=ty-g.rotation.y;dr=Math.atan2(Math.sin(dr),Math.cos(dr));g.rotation.y+=dr*Math.min(1,dt*5);
      g.position.x+=(b.hole.x-g.position.x)*Math.min(1,dt*4);g.position.z+=(b.hole.z-g.position.z)*Math.min(1,dt*4);
      g.position.y=groundAt(g.position.x,g.position.z);
      animPerson(b.p,2,dt,b.dph%1);
      if(b.hole.d>=crewDepth(b)){
        b.state='rest';b.t=(6+botRng()*6)*crewThirst(b);b.restT=0;b.bucket=Math.min(crewBucketMax(b),(b.bucket||0)+crewDepth(b)/FIVE_FT);   /* a hand-dug hole is a third of a hole of sand */
        if(botRng()<0.3){const ty2=['cap','can','spoon'][Math.floor(botRng()*3)];popItem({type:ty2},b.hole.x,b.hole.z);say(b.L,{cap:'Just a bottle cap. Figures.',can:'A rusty can. Great.',spoon:'Somebody lost a spoon out here.'}[ty2])}
      }
    }else if(b.state==='rest'){
      b.restT+=dt;b.t-=dt;
      g.position.y=groundAt(g.position.x,g.position.z);
      animPerson(b.p,b.restT<2.2?5:b.restT<3.8?6:0,dt);
      if(b.t<=0){
        /* at night the crew heads back to D Tent to sleep; by day they'll wander over for a break sometimes */
        if(b.stam<45){b.t=2;continue}   // still catching his breath
        if(b.water<crewWaterMax(b)*CREW_WATER_LOW){b.errand='water';b.state='gateout';b.tx=CREW_GATE.x;b.tz=CREW_GATE.out;say(b.L,pick(['I need water.','Canteen\'s dry. Back in a minute.','So thirsty...']),2600)}
        else if(b.bucket>=crewBucketMax(b)-1e-6&&!crewSifts(b)){b.errand='pan';b.state='gateout';b.tx=CREW_GATE.x;b.tz=CREW_GATE.out;say(b.L,pick(['Pan\'s full. Off to wash it.','Got a pan of sand. Back soon.']),2600)}
        else if(b.bucket>=crewBucketMax(b)-1e-6){b.errand='sift';b.state='gateout';b.tx=CREW_GATE.x;b.tz=CREW_GATE.out;say(b.L,pick(['Bucket\'s full. Off to the sifter.','That\'s a full bucket. Sifter time.','Full bucket. Back in a bit.']),3000)}
        else if(botRng()<0.12*crewThirst(b)){b.state='gateout';b.tx=0;b.tz=25}   // a daytime break in D Tent now and then (the siren sends everyone home)
        else{const sp=crewDigSpot(b,b.hole.x,b.hole.z);if(sp){b.tx=sp.x;b.tz=sp.z;b.state='walk'}else b.t=4}
      }
    }else if(b.state==='siftq'){
      const i=SIFTQ.indexOf(b),[sx,sz]=siftSlot(i);
      if(!walkTo(b,sx,sz,dt,2.2)){continue}
      const G=SIM.GOLD.SIFTER,fx=i===0?G.x-0.8:siftSlot(i-1)[0],fz=i===0?G.z:siftSlot(i-1)[1];   // face the hopper, or the back of the one ahead
      let dr=Math.atan2(fx-g.position.x,fz-g.position.z)-g.rotation.y;dr=Math.atan2(Math.sin(dr),Math.cos(dr));g.rotation.y+=dr*Math.min(1,dt*5);
      animPerson(b.p,0,dt);
      if(i===0){b.waitT=(b.waitT||0)+dt;if(!humanAtSifter()||b.waitT>10){b.state='sifting';b.t=3.6;b.puffT=0}}
    }else if(b.state==='drink'){   // to the water drums, fill up, back out
      const W=SIM.GOLD.WATER,k=bots.indexOf(b),wx=W.x+1.2+Math.cos(k*1.05)*0.9,wz=W.z-1.6+Math.sin(k*1.05)*0.6;
      if(b.t==null){if(!walkTo(b,wx,wz,dt,2.4))continue;b.t=2.2;if(nearCam(wx,wz,25))sfx.splash()}
      animPerson(b.p,5,dt);   // the Drink clip
      if((b.t-=dt)<=0){b.water=crewWaterMax(b);b.t=null;b.errand=null;
        /* his pan, washed at the drums: the gold goes in the crew bank (a water-only trip leaves his sand be) */
        if(b.wash){if(b.bucket>0.05){const r=SIM.siftGold(b.bucket,botRng,tune('gold.perHole'),RUN.mood==='digday'?2:1);crewDeposit(b,r.gold);say(b.L,pick(['A bit of color. Crew bank.','Washed out. Into the bank.']),2600)}b.bucket=0}
        b.wash=false;b.state='gatebackin';b.tx=CREW_GATE.x;b.tz=CREW_GATE.in}
    }else if(b.state==='sifting'){
      const G=SIM.GOLD.SIFTER;b.t-=dt;animPerson(b.p,b.t>2.8?2:0,dt,b.t>2.8?(3.6-b.t)/0.8:0);   // tip the bucket in, then watch it shake
      if((b.puffT-=dt)<=0&&nearCam(G.x,G.z,30)){b.puffT=0.6;puff(G.x+(botRng()-0.5)*1.2,groundAt(G.x,G.z)+1.1,G.z+(botRng()-0.5)*0.8,G.x,G.z,6);if(nearCam(G.x,G.z,18))noise(0.25,500,0.5,0.06,'bandpass')}
      if(b.t<=0){
        const r=SIM.siftGold(b.bucket||CREW_HOLES,botRng,tune('gold.perHole'),RUN.mood==='digday'?2:1);
        crewDeposit(b,r.gold);say(b.L,r.nugget?'A nugget! Into the crew bank.':r.luck>1.4?'Good batch. Into the crew bank.':pick(['Into the crew bank.','For the crew.','There. Crew bank.']),3200);
        b.bucket=0;b.errand=null;leaveSiftQ(b);if(b.water<crewWaterMax(b)*0.7){b.state='drink';b.t=null}else{b.state='gatebackin';b.tx=CREW_GATE.x;b.tz=CREW_GATE.in}
      }
    }else{
      const dx=b.tx-g.position.x,dz=b.tz-g.position.z,d=Math.hypot(dx,dz);
      if(d<0.1&&b.state==='return'){b.tx=b.tz=0;b.state=b.hole.d>=crewDepth(b)?'rest':'dig';b.t=2;b.restT=0;b.dph=0}
      else if(d<0.1&&b.state==='gateout'){b.state='gatein';b.tx=0;b.tz=30}
      else if(d<0.1&&b.state==='gatein'&&b.errand==='sift'){b.state='siftq';SIFTQ.push(b);b.waitT=0}
      else if(d<0.1&&b.state==='gatein'&&(b.errand==='water'||b.errand==='pan')){b.state='drink';b.wash=b.errand==='pan';b.t=null}
      else if(d<0.1&&b.state==='gatein'){b.state='gotent';b.tx=D_TENT_DOOR.x;b.tz=D_TENT_DOOR.z}
      else if(d<0.1&&b.state==='gotent'){g.position.set(D_ENTRY.x,TENT_FLOOR_Y,D_ENTRY.z);goIndoor(b,[RACK[bots.indexOf(b)].front],'rack')}   // in through the flap, straight to the rack
      else if(d<0.1&&b.state==='gatebackin'){b.state='gatebackout';b.tx=0;b.tz=25}
      else if(d<0.1&&b.state==='gatebackout'){const sp=b.hole.d>=crewDepth(b)&&crewDigSpot(b,b.hole.x,b.hole.z);if(sp){b.state='walk';b.tx=sp.x;b.tz=sp.z}else{b.state='return';b.tx=b.hole.x;b.tz=b.hole.z}}   // that hole's done: new ground
      else if(d<0.1){b.hole=addHole({x:b.tx,z:b.tz,d:0.05,bot:true});b.tx=b.tz=0;b.state='dig';b.dph=0;touchHole(b.hole)}
      else walkTo(b,b.tx,b.tz,dt,siren?3.6:b.state==='return'?3.5:2.2);
    }
  }
}
